using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Informs TDLib that the message content has been opened (e.g., the user has opened a photo, video, document, location or venue, or has listened to an audio file or voice note message).
    /// An updateMessageContentOpened update will be generated if something has changed
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> OpenMessageContentAsync(long chatId = default, long messageId = default)
    {

           using var activity =  StartCallActivity("OpenMessageContentAsync", typeof(OpenMessageContent).FullName ?? "OpenMessageContentAsync");

           try
           {
             return client.OpenMessageContentAsync(chatId, messageId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
// REUSE-IgnoreEnd